sys_script_include.script:
var DayOneTaskGenerator = Class.create();
DayOneTaskGenerator.prototype = {
    initialize: function(planSysId) {
        this.planSysId = planSysId;
    },

    generateTasks: function() {
        var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
        if (!planGr.get(this.planSysId)) {
            gs.warn('DayOneTaskGenerator: Plan not found: ' + this.planSysId);
            return;
        }

        var planRole = planGr.getValue('role') || '';
        var planLocation = planGr.getValue('location') || '';
        var joiningDate = planGr.getValue('joining_date') || '';

        // Query active task templates matching role and location
        var templateGr = new GlideRecord('x_1919740_dayone_0_task_template');
        templateGr.addQuery('active', true);
        templateGr.query();

        while (templateGr.next()) {
            var appliesToRoles = templateGr.getValue('applies_to_roles') || '*';
            var appliesToLocations = templateGr.getValue('applies_to_locations') || '*';

            // Check role match (wildcard * matches all)
            if (appliesToRoles != '*' && appliesToRoles.indexOf(planRole) < 0) {
                continue;
            }

            // Check location match (wildcard * matches all)
            if (appliesToLocations != '*' && appliesToLocations.indexOf(planLocation) < 0) {
                continue;
            }

            var templateName = templateGr.getValue('template_name');

            // Duplicate prevention: check if task already exists with same plan and template_name
            var existingGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
            existingGr.addQuery('plan', this.planSysId);
            existingGr.addQuery('task_name', templateName);
            existingGr.query();

            if (existingGr.hasNext()) {
                continue;
            }

            var estDays = parseInt(templateGr.getValue('est_days_to_complete'), 10) || 0;

            // Create new task
            var taskGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
            taskGr.initialize();
            taskGr.setValue('plan', this.planSysId);
            taskGr.setValue('task_name', templateName);
            taskGr.setValue('department', templateGr.getValue('department'));
            taskGr.setValue('mandatory', templateGr.getValue('mandatory'));
            taskGr.setValue('est_remaining_days', estDays);
            taskGr.setValue('description', templateGr.getValue('description'));
            taskGr.setValue('task_state', 'open');

            // Calculate due_date = joining_date - est_days_to_complete
            if (joiningDate && estDays > 0) {
                var dueDate = new GlideDateTime(joiningDate);
                dueDate.addDaysUTC(-estDays);
                taskGr.setValue('due_date', dueDate.getValue());
            }

            taskGr.insert();
        }
    },

    type: 'DayOneTaskGenerator'
};
